def process(inputs):
    # Zero-token tabular schema normalization
    import json
    if isinstance(inputs, str):
        try:
            data = json.loads(inputs)
        except:
            data = {"raw": inputs}
    else:
        data = inputs or {}

    item = data.get("item", data)
    return {
        "record_id": item.get("id", "REC-001"),
        "sender": item.get("from", "Unknown"),
        "subject": item.get("subject", "No Subject"),
        "received_at": item.get("receivedDateTime", ""),
        "has_attachments": item.get("hasAttachments", False),
        "summary": (item.get("bodyPreview") or item.get("content") or "")[:120],
        "status": "EXTRACTED"
    }

